#include <openssl/rand.h>

int main() {
    unsigned char salt[32];
    unsigned char hash[32];

    // Test with an empty password
    const char* password = "";
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password),
                           salt, 32,
                           10000, EVP_sha256(),
                           hash)) {
        printf("Hashing failed for empty password\n");
        return EXIT_FAILURE;
    }

    // Test with a longer password
    const char* long_password = "This is a very long password to test the hashing function";
    unsigned char long_salt[32];
    unsigned char long_hash[32];
    if (!PKCS5_PBKDF2_HMAC(long_password, strlen(long_password),
                           long_salt, 32,
                           10000, EVP_sha256(),
                           long_hash)) {
        printf("Hashing failed for long password\n");
        return EXIT_FAILURE;
    }

    printf("Successfully hashed both empty and long passwords\n");
    return EXIT_SUCCESS;
}

