#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <time.h>

#define SALT_LENGTH 32
#define HASH_LENGTH 32

int main() {
    unsigned char salt[SALT_LENGTH];
    unsigned char hash[HASH_LENGTH];
    const char *password = "userpassword";
    int iterations[] = {1000, 10000, 50000, 100000};

    // Generate a random salt
    RAND_bytes(salt, SALT_LENGTH);

    printf("Iteration Count vs. Time (seconds)\n");
    for (int i = 0; i < 4; ++i) {
        clock_t start_time = clock();

        PKCS5_PBKDF2_HMAC(password, strlen(password),
                          salt, SALT_LENGTH,
                          iterations[i], EVP_sha256(),
                          hash);

        clock_t end_time = clock();
        double elapsed = (double)(end_time - start_time) / CLOCKS_PER_SEC;

        printf("%d iterations: %.6f seconds\n", iterations[i], elapsed);
    }

    return 0;
}
